var dc = tree.current_scene.deployment_controller
var r0 = float(InputDeviceManager.get_meta("r0"))
return absf(dc.reposition_ghost.get_base_rotation() - r0)

var dc = tree.current_scene.deployment_controller
var r0 = float(InputDeviceManager.get_meta("r0"))
return absf((dc.reposition_ghost.get_base_rotation() - r0) - (PI / 6.0))

var dc = tree.current_scene.deployment_controller
var r0 = float(InputDeviceManager.get_meta("r0"))
return absf(dc.temp_rotations[0] - r0)

var dc = tree.current_scene.deployment_controller
var r0 = float(InputDeviceManager.get_meta("r0"))
return absf((dc.temp_rotations[0] - r0) - (PI / 6.0))

var dc = tree.current_scene.deployment_controller
var p0 = InputDeviceManager.get_meta("p0")
return float(p0.distance_to(dc.temp_positions[0]))
